/* =======================================================================
   LOGO +BPM 165 EN 3D — Three.js

   Le logo complet d'origine (plaque hexagonale verte, contour noir, rond
   rouge pour "165"), tel qu'il existait avant le traitement "découpé /
   transparent" : une plaque PLEINE et OPAQUE, aucun effet de vide ni de
   transparence à travers les lettres — juste le vrai dessin du logo,
   texture appliquée sur une forme 3D qui reprend son contour exact.

   Rotation continue et réelle à 360° sur l'axe Y, en boucle, pour toute
   la durée de la soirée — vitesse et rythme inchangés.
   ======================================================================= */

(function () {
  // --- Contour vectoriel du badge complet (plaque + rond), extrait du
  // vrai dessin d'origine (assets/logo_face.png). Un seul contour : la
  // plaque et le rond du "165" se touchent dans le dessin, donc pas de
  // trou à gérer ici (les lettres/chiffres sont juste peints SUR la
  // plaque, ce ne sont plus des découpes dans la géométrie).
  const OUTLINE = [[0.93819,0.91265],[0.89073,0.93976],[0.83996,0.94127],[0.79029,0.91717],[0.74503,0.85693],[0.72848,0.85693],[0.50773,0.98795],[0.50552,1.0],[0.43929,1.0],[0.43377,0.98645],[0.04746,0.75904],[0.0,0.71235],[0.0,0.29819],[0.04415,0.25151],[0.43598,0.01355],[0.43819,0.00151],[0.50883,0.00151],[0.51545,0.01657],[0.89073,0.24849],[0.91832,0.27711],[0.93709,0.3238],[0.93929,0.59639],[0.97461,0.64608],[0.99117,0.69578],[0.9989,0.69729],[0.9989,0.81627],[0.99117,0.81777],[0.96026,0.88855]];

  // Centre de la forme (centre de son cadre), utilisé pour la positionner
  // et faire pivoter le badge autour de son propre milieu.
  const CENTER_X = 0.5;
  const CENTER_Y = 0.5;

  const canvas = document.getElementById('logo3d-canvas');
  if (!canvas || !window.THREE) return;

  // --- Scène, caméra, rendu (inchangé) -----------------------------------
  const scene = new THREE.Scene();

  const camera = new THREE.PerspectiveCamera(32, 1, 0.1, 100);
  camera.position.set(0, 0, 7.5);

  const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;

  function resize() {
    const w = canvas.clientWidth, h = canvas.clientHeight;
    if (!w || !h) return;
    if (canvas.width === w && canvas.height === h) return;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  }
  window.addEventListener('resize', resize);

  // --- Construction de la forme (un seul contour, pas de trou) -----------
  function buildShape(points) {
    const s = new THREE.Shape();
    s.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) s.lineTo(points[i][0], points[i][1]);
    s.closePath();
    return s;
  }

  const badgeShape = buildShape(OUTLINE);

  // Le logo est un petit Group : un corps plein (tranche + dos, vert,
  // opaque) + une plaque texturée collée sur l'avant avec le vrai dessin
  // (plaque verte, contour noir, rond rouge, "+BPM 165") — opaque elle
  // aussi, sans aucun effet de transparence.
  const logo = new THREE.Group();
  scene.add(logo);

  const DEPTH = 0.105;
  const extrudeSettings = {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: 0.0125,
    bevelSize: 0.01,
    bevelSegments: 3,
    curveSegments: 24,
  };

  // --- Corps extrudé (tranche + dos) --------------------------------------
  const bodyGeometry = new THREE.ExtrudeGeometry(badgeShape, extrudeSettings);
  bodyGeometry.scale(4, 4, 4);

  bodyGeometry.computeBoundingBox();
  const zMin = bodyGeometry.boundingBox.min.z;
  const zMax = bodyGeometry.boundingBox.max.z;
  const zCenter = (zMin + zMax) / 2;
  const bodyFrontZ = zMax - zCenter;

  const OFFSET_X = -CENTER_X * 4;
  const OFFSET_Y = -CENTER_Y * 4;

  bodyGeometry.translate(OFFSET_X, OFFSET_Y, -zCenter);

  const bodyMaterial = new THREE.MeshStandardMaterial({
    color: 0x0d3d1f,
    metalness: 0.35,
    roughness: 0.4,
    emissive: 0x0fae55,
    emissiveIntensity: 0.3,
    transparent: false,
  });

  const bodyFront = new THREE.Mesh(bodyGeometry, bodyMaterial);
  logo.add(bodyFront);

  // --- Corps "arrière" : un vrai relief, pas juste une texture ----------
  // Un corps extrudé est un objet RIGIDE : il tourne avec tout le badge,
  // donc à 180°, le relief se retrouverait à l'envers et déplacé si on ne
  // faisait rien — on construit un DEUXIÈME corps, avec la même astuce de
  // rotation à 180° cuite dans la géométrie, et on bascule entre les deux
  // (jamais les deux en même temps).
  const bodyGeometryBack = new THREE.ExtrudeGeometry(badgeShape, extrudeSettings);
  bodyGeometryBack.scale(4, 4, 4);
  bodyGeometryBack.rotateY(Math.PI);
  bodyGeometryBack.translate(-OFFSET_X, OFFSET_Y, zCenter);

  const bodyBack = new THREE.Mesh(bodyGeometryBack, bodyMaterial);
  logo.add(bodyBack);

  // La texture est encodée directement ici (pas chargée depuis un fichier
  // séparé) : un WebGL qui tourne en file:// (double-clic, sans serveur)
  // refuse de charger une image locale dans une texture — "cross-origin
  // data" — quel que soit le réglage crossOrigin. Une image encodée en
  // data: URI n'a pas ce problème. C'est le dessin ORIGINAL complet du
  // logo (plaque verte, contour noir, rond rouge, "+BPM 165"), opaque.
  const LOGO_FACE_DATA_URI = "data:image/webp;base64,";

  const texture = new THREE.TextureLoader().load(LOGO_FACE_DATA_URI);
  texture.encoding = THREE.sRGBEncoding;

  // --- Face avant texturée -------------------------------------------------
  const faceGeometry = new THREE.ShapeGeometry(badgeShape, 24);
  faceGeometry.scale(4, 4, 4);
  faceGeometry.translate(OFFSET_X, OFFSET_Y, bodyFrontZ + 0.01);

  const faceMaterial = new THREE.MeshStandardMaterial({
    map: texture,
    color: 0xffffff,
    metalness: 0.1,
    roughness: 0.5,
    emissive: 0x1a5c2f,
    emissiveIntensity: 0.06,
    transparent: false,
  });

  const faceFront = new THREE.Mesh(faceGeometry, faceMaterial);
  logo.add(faceFront);

  // --- Face arrière : EXACTEMENT le même dessin (même texture), collée
  // derrière le corps. Retournée à 180° sur Y avant d'être placée, avec le
  // MÊME centre partagé : ainsi, quand tout le groupe "logo" aura lui-même
  // tourné de 180°, cette rotation "cuite dans la géométrie" + la rotation
  // du groupe s'annulent exactement, et le logo apparaît bien droit et à
  // l'endroit (jamais en miroir, jamais à l'envers).
  const faceGeometryBack = new THREE.ShapeGeometry(badgeShape, 24);
  faceGeometryBack.scale(4, 4, 4);
  faceGeometryBack.rotateY(Math.PI);
  faceGeometryBack.translate(-OFFSET_X, OFFSET_Y, -(bodyFrontZ + 0.01));

  const faceBack = new THREE.Mesh(faceGeometryBack, faceMaterial);
  logo.add(faceBack);

  const allMaterials = [bodyMaterial, faceMaterial];

  // --- Éclairage néon (inchangé) ------------------------------------------
  scene.add(new THREE.AmbientLight(0x1a3324, 0.8));

  const key = new THREE.PointLight(0x5bffa0, 1.3, 20, 2);
  key.position.set(3, 3, 6);
  scene.add(key);

  const rim = new THREE.PointLight(0x30ff90, 0.9, 20, 2);
  rim.position.set(-4, -2, 3);
  scene.add(rim);

  const fill = new THREE.DirectionalLight(0xbfffdc, 0.35);
  fill.position.set(0, 4, 2);
  scene.add(fill);

  // --- Animation : apparition, rotation continue, pulsation --------------
  const clock = new THREE.Clock();
  const ROT_SPEED = 0.42; // rad/s — un tour complet toutes les ~15s (inchangé)

  function animate() {
    requestAnimationFrame(animate);
    const t = clock.getElapsedTime();

    // apparition progressive au tout début (pilotée par timeline.js si
    // présent, sinon apparition simple sur les 3 premières secondes) — le
    // logo étant maintenant opaque (plus d'effet de transparence), c'est
    // l'échelle qui porte l'apparition : il "grandit" légèrement à
    // l'arrivée au lieu de se fondre depuis l'invisible.
    const intro = (window.BeldaTimeline && typeof window.BeldaTimeline.logoIntro === 'number')
      ? window.BeldaTimeline.logoIntro
      : Math.min(1, t / 3.0);

    const eased = intro * intro * (3 - 2 * intro); // smoothstep
    logo.scale.setScalar(0.82 + 0.18 * eased);

    // rotation réelle et continue sur l'axe Y (tour complet à 360°) — pas
    // à vitesse constante : elle ralentit quand la face ou le dos font
    // face à la caméra (pour laisser le temps de lire "+BPM 165") et
    // accélère en passant par la tranche. Toujours dans le même sens,
    // jamais de pause ni de retour en arrière — rythme inchangé.
    const phase = t * ROT_SPEED;
    const EASE_AMOUNT = 0.4;
    logo.rotation.y = phase - EASE_AMOUNT * Math.sin(2 * phase);
    // petit tangage doux pour la profondeur, jamais assez pour cacher la face
    logo.rotation.x = Math.sin(t * 0.35) * 0.06;
    logo.position.y = Math.sin(t * 0.5) * 0.06;

    // Bascule explicite avant/arrière : le tri automatique des faces
    // avant/arrière par le GPU n'est pas fiable à 100% sur une forme
    // découpée — on affiche donc nous-mêmes la bonne face selon l'angle,
    // jamais les deux à la fois, jamais de relief ou de texte fantôme.
    const facingFront = Math.cos(logo.rotation.y) > 0;
    faceFront.visible = facingFront;
    bodyFront.visible = facingFront;
    faceBack.visible = !facingFront;
    bodyBack.visible = !facingFront;

    // pulsation lumineuse subtile (inchangée)
    const pulse = 0.85 + 0.15 * Math.sin(t * 1.6);
    bodyMaterial.emissiveIntensity = 0.3 * pulse;
    faceMaterial.emissiveIntensity = 0.06 * pulse;

    resize();
    renderer.render(scene, camera);
  }

  resize();
  animate();
})();